-- 008_game_portal_bot_definition.sql
--
-- Schema de configuration du module game-portal (32 champs), repris a
-- l'identique de sentinel-api/migrations/001_init.sql avant le commit
-- 0e5549a7. La migration 007 n'avait seede que 'game-bot' (catalogue des jeux
-- mentionnables), pas 'game-portal' (serveurs de jeu) : sans cette ligne,
-- aucune interface ne peut proposer 'session_category_id' et le bot ne sait
-- pas ou creer les salons de session.
--
-- Cle lue par nexus-bot : MODULE_BOT_NAME = "game-portal".

INSERT INTO bot_definitions VALUES ('game-portal', 'Game Portal', 'Plateforme de serveurs de jeux (Minecraft, Valheim, Terraria, Palworld, etc.). Gere quotas, allocation de ports, cycle de vie des containers (health check RCON, idle shutdown, reconciliation DB <-> Docker, image cleanup) et notifications Discord.', '[{"key": "enabled", "type": "boolean", "label": "Module actif", "default": "true", "required": false, "description": "Active la plateforme Game Portal pour cette guild. Si OFF : aucun serveur ne peut etre cree, demarre, ou monitore."}, {"key": "log_channel_id", "type": "channel", "label": "Salon Discord de logs", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Salon ou le bot poste les events critiques (crash detected, idle shutdown, backup created, etc.)."}, {"key": "max_servers_per_guild", "max": 100, "min": 1, "type": "number", "label": "Serveurs max par guild", "default": "5", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Limite stricte du nombre de serveurs (toutes templates confondues) qu une guild peut creer simultanement."}, {"key": "max_memory_total_mb", "min": 512, "type": "number", "unit": "Mo", "label": "Memoire RAM totale autorisee", "default": "8192", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Plafond cumule de la memoire allouee a tous les serveurs running."}, {"key": "allowed_templates", "type": "text", "label": "Templates autorises (CSV slugs)", "default": "minecraft-vanilla", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Whitelist des slugs de templates utilisables (separes par virgule)."}, {"key": "port_range_start", "max": 65535, "min": 1024, "type": "number", "label": "Port min range jeu", "default": "25500", "required": false, "depends_on": {"key": "enabled", "equals": "true"}}, {"key": "port_range_end", "max": 65535, "min": 1024, "type": "number", "label": "Port max range jeu", "default": "25599", "required": false, "depends_on": {"key": "enabled", "equals": "true"}}, {"key": "rcon_enabled", "type": "boolean", "label": "RCON actif globalement", "default": "true", "required": false, "depends_on": {"key": "enabled", "equals": "true"}}, {"key": "rcon_port_range_start", "max": 65535, "min": 1024, "type": "number", "label": "Port min range RCON", "default": "25700", "required": false, "depends_on": {"key": "rcon_enabled", "equals": "true"}}, {"key": "rcon_port_range_end", "max": 65535, "min": 1024, "type": "number", "label": "Port max range RCON", "default": "25799", "required": false, "depends_on": {"key": "rcon_enabled", "equals": "true"}}, {"key": "rcon_timeout_secs", "max": 60, "min": 1, "type": "number", "unit": "s", "label": "Timeout RCON par requete", "default": "5", "required": false, "depends_on": {"key": "rcon_enabled", "equals": "true"}}, {"key": "docker_network_name", "type": "text", "label": "Network Docker isole", "default": "sentinel-games", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Network Docker dedie aux containers de jeux. Cree automatiquement si absent."}, {"key": "container_user", "type": "text", "label": "User UID:GID containers", "default": "1000:1000", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "User non-root applique aux containers (--user). Format: UID:GID."}, {"key": "host_data_dir", "type": "text", "label": "Repertoire host volumes", "default": "/var/lib/sentinel/games", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Repertoire host ou les volumes Docker nommes sont stockes."}, {"key": "auto_create_world_volume", "type": "boolean", "label": "Creer volume world auto", "default": "true", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Cree automatiquement un volume Docker nomme pour persister le monde du jeu."}, {"key": "health_check_interval_secs", "max": 600, "min": 10, "type": "number", "unit": "s", "label": "Worker : intervalle health check", "default": "30", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Frequence de verification etat serveurs (RCON ping, player count, status container)."}, {"key": "default_idle_shutdown_days", "max": 365, "min": 0, "type": "number", "unit": "j", "label": "Idle shutdown (jours sans joueur)", "default": "7", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Si aucun joueur ne se connecte pendant ce nombre de jours, le worker arrete automatiquement le serveur. 0 = desactive."}, {"key": "idle_shutdown_check_interval_secs", "max": 86400, "min": 300, "type": "number", "unit": "s", "label": "Worker : intervalle scan idle", "default": "3600", "required": false, "depends_on": {"key": "default_idle_shutdown_days", "equals": ""}, "description": "Frequence de scan des serveurs idle."}, {"key": "reconciler_interval_secs", "max": 86400, "min": 300, "type": "number", "unit": "s", "label": "Worker : intervalle reconciler DB <-> Docker", "default": "3600", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Frequence de reconciliation entre la table game_servers et la realite Docker."}, {"key": "auto_remove_unused_images", "type": "boolean", "label": "Suppression auto images non utilisees", "default": "true", "required": false, "depends_on": {"key": "enabled", "equals": "true"}, "description": "Supprime les images Docker des templates non utilises depuis N jours. Liberation disque (Minecraft 500 MB, Palworld 8 GB)."}, {"key": "unused_image_grace_days", "max": 365, "min": 0, "type": "number", "unit": "j", "label": "Jours de grace avant suppression image", "default": "7", "required": false, "depends_on": {"key": "auto_remove_unused_images", "equals": "true"}, "description": "0 = desactive. Si tu relances un serveur, l image se re-pull automatiquement."}, {"key": "image_cleanup_interval_secs", "max": 604800, "min": 3600, "type": "number", "unit": "s", "label": "Worker : intervalle nettoyage images", "default": "86400", "required": false, "depends_on": {"key": "auto_remove_unused_images", "equals": "true"}, "description": "Frequence de scan des images Docker de templates non utilises a supprimer (liberation disque)."}, {"key": "restart_backoff_base_secs", "max": 3600, "min": 1, "type": "number", "unit": "s", "label": "Auto-restart : base du backoff (secondes)", "default": "30", "required": false, "depends_on": {"key": "auto_restart_on_crash", "equals": "true"}, "description": "Delai de base du backoff exponentiel (base * 2^tentatives) entre deux redemarrages auto apres crash."}, {"key": "restart_backoff_cap_secs", "max": 86400, "min": 1, "type": "number", "unit": "s", "label": "Auto-restart : plafond du backoff (secondes)", "default": "3600", "required": false, "depends_on": {"key": "auto_restart_on_crash", "equals": "true"}, "description": "Plafond du delai de backoff entre deux redemarrages auto (ne monte jamais au-dela, meme apres de nombreuses tentatives)."}, {"key": "stuck_transition_threshold_minutes", "max": 1440, "min": 1, "type": "number", "unit": "min", "label": "Reconciler : seuil etat transitoire bloque (minutes)", "default": "10", "required": false, "description": "Au-dela de ce delai dans un etat Starting/Stopping sans progression, le reconciler force la resolution (Error ou etat reel du container)."}, {"key": "stop_timeout_secs", "max": 600, "min": 1, "type": "number", "unit": "s", "label": "Arret : delai de grace avant kill (secondes)", "default": "30", "required": false, "description": "Delai laisse a un container pour s''arreter proprement (docker stop -t) avant kill force."}, {"key": "max_log_lines", "max": 5000, "min": 1, "type": "number", "unit": "lignes", "label": "Logs : nombre max de lignes par requete", "default": "1000", "required": false, "description": "Borne dure du nombre de lignes de logs recuperables en une seule requete (protege la memoire et la taille du payload)."}, {"key": "session_category_id", "type": "category", "label": "Categorie des salons de session de jeu", "required": false}, {"key": "ip_reveal_default_days", "type": "number", "label": "Delai avant revelation de l IP (jours)", "default": "7", "required": false}, {"key": "session_daily_ping_enabled", "type": "boolean", "label": "Ping quotidien du role pendant l attente", "default": "false", "required": false}, {"key": "session_daily_ping_hour", "type": "number", "label": "Heure du ping quotidien (0-23, UTC)", "default": "18", "required": false}, {"key": "session_public_host", "type": "text", "label": "Hote public du serveur (IP ou domaine, affiche a la revelation)", "required": false}]') ON CONFLICT (bot_name) DO NOTHING;
